<script setup lang="ts">
import {useProductivityStore,dateKey} from '~/stores/productivity'; import type {Priority,Task} from '~/types/domain'
const store=useProductivityStore(); const q=ref(''); const filter=ref('open'); const open=ref(false); const editing=ref<string|null>(null); const title=ref(''); const priority=ref<Priority>('medium'); const minutes=ref(30); const date=ref(dateKey()); const start=ref(''); const end=ref(''); const projectId=ref(''); const goalId=ref('')
const list=computed(()=>store.tasks.filter(t=>(filter.value==='all'||(filter.value==='open'?t.status!=='completed':t.status===filter.value))&&t.title.includes(q.value)))
const reset=()=>{title.value='';priority.value='medium';minutes.value=30;date.value=dateKey();start.value='';end.value='';projectId.value='';goalId.value='';editing.value=null}
const save=()=>{if(!title.value.trim())return;if(editing.value)store.updateTask(editing.value,{title:title.value,priority:priority.value,estimatedMinutes:minutes.value,scheduledDate:date.value||undefined,startTime:start.value||undefined,endTime:end.value||undefined,projectId:projectId.value||undefined,goalId:goalId.value||undefined});else store.addTask({title:title.value,priority:priority.value,category:'other',estimatedMinutes:minutes.value,scheduledDate:date.value||undefined,startTime:start.value||undefined,endTime:end.value||undefined,projectId:projectId.value||undefined,goalId:goalId.value||undefined});open.value=false;reset()}
const edit=(t:Task)=>{editing.value=t.id;title.value=t.title;priority.value=t.priority;minutes.value=t.estimatedMinutes;date.value=t.scheduledDate||'';start.value=t.startTime||'';end.value=t.endTime||'';projectId.value=t.projectId||'';goalId.value=t.goalId||'';open.value=true}
</script>
<template><div class="space-y-5"><div class="flex justify-between gap-3"><div><h1 class="text-2xl font-black">کارها</h1><p class="text-gray-500">یک بار بساز، بارها استفاده کن؛ و هر چیزی قابل ویرایش یا حذف است.</p></div><UButton icon="i-lucide-plus" @click="open=true">کار جدید</UButton></div><div class="flex gap-3"><UInput v-model="q" icon="i-lucide-search" placeholder="جستجو..." class="max-w-sm"/><USelect v-model="filter" :items="[{label:'باز',value:'open'},{label:'همه',value:'all'},{label:'تمام‌شده',value:'completed'},{label:'درحال‌انجام',value:'in_progress'},{label:'تعویق',value:'deferred'}]" value-key="value" class="w-44"/></div><UCard><div v-if="list.length" class="space-y-2"><div v-for="t in list" :key="t.id" class="p-3 rounded-2xl border border-gray-200 dark:border-gray-800 flex gap-3 items-center"><UCheckbox :model-value="t.status==='completed'" @update:model-value="store.toggleTask(t.id)"/><div class="flex-1 min-w-0"><b :class="t.status==='completed'?'line-through text-gray-400':''">{{t.title}}</b><p class="text-xs text-gray-500 mt-1">{{t.scheduledDate||'بدون تاریخ'}} · {{t.startTime||'بدون ساعت'}} · {{t.estimatedMinutes}}دقیقه</p></div><UBadge variant="soft">{{t.priority}}</UBadge><UButton icon="i-lucide-copy" variant="ghost" @click="store.duplicateTask(t.id,dateKey())"/><UButton icon="i-lucide-pencil" variant="ghost" @click="edit(t)"/><UButton icon="i-lucide-trash-2" variant="ghost" color="error" @click="store.deleteTask(t.id)"/></div></div><p v-else class="text-center text-gray-500 py-8">کاری پیدا نشد.</p></UCard><UModal v-model:open="open"><template #content><UCard><template #header><b>{{editing?'ویرایش کار':'ساخت کار'}}</b></template><div class="space-y-4"><UInput v-model="title" placeholder="مثلاً مطالعه DHCP"/><div class="grid grid-cols-2 gap-3"><USelect v-model="priority" :items="['low','medium','high','critical']"/><UInput v-model.number="minutes" type="number" min="1" placeholder="دقیقه"/></div><div class="grid grid-cols-3 gap-3"><UFormField label="تاریخ"><UInput v-model="date" type="date"/></UFormField><UFormField label="شروع"><UInput v-model="start" type="time"/></UFormField><UFormField label="پایان"><UInput v-model="end" type="time"/></UFormField></div><div class="grid grid-cols-2 gap-3"><USelect v-model="projectId" :items="[{label:'بدون پروژه',value:''},...store.projects.map(p=>({label:p.title,value:p.id}))]" value-key="value"/><USelect v-model="goalId" :items="[{label:'بدون هدف',value:''},...store.goals.map(g=>({label:g.title,value:g.id}))]" value-key="value"/></div><div class="flex justify-end gap-2"><UButton variant="ghost" @click="open=false;reset()">انصراف</UButton><UButton @click="save">ذخیره</UButton></div></div></UCard></template></UModal></div></template>
